// Explicitly requested LEVEL test cheat; these are the original mode-specific stages.
export function createLevelOverlay({getGame,onSelect}) {
  let panel=null,openedGame=null,previouslyPaused=false,restoreFocus=null;
  const styles=document.createElement('style');styles.textContent=`.level-overlay{position:absolute;inset:0;z-index:80;background:#080807f5;display:grid;place-items:center;padding:max(16px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(16px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left));overflow:auto}.level-overlay[hidden]{display:none}.level-card{width:min(600px,100%);max-height:90dvh;overflow:auto;padding:22px;background:#141410;border:1px solid #665d3d;color:#eee8d5}.level-card h2{margin:0 0 8px;font:700 22px 'Courier New',monospace}.level-card p{font:13px/1.5 sans-serif;color:#c3bfaf}.level-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:8px;margin:12px 0}.level-grid button{min-height:44px;padding:10px;background:#24231b;color:#eee8d5;border:1px solid #675f43;border-radius:4px}.level-grid button:hover,.level-grid button:focus-visible{background:#4b4228;outline:2px solid #d7bd72}.level-current{color:#e5c77b!important}.level-close{min-height:44px;padding:9px 20px;border:1px solid #756a49;color:#eee8d5;background:#24231b}.level-status{min-height:20px;color:#ffd08a!important}`;document.head.append(styles);
  function available(){const g=getGame();return !!(g?.started&&g.simulation?.jumpToStage&&!['title','password'].includes(g.sequence?.kind));}
  function choices(){const g=getGame(),sim=g?.simulation;if(!sim)return[];const n=sim.mode==='arcade'?8:sim.mode==='beginner'?3:sim.playerCount===2?2:15;const rows=Array.from({length:n},(_,index)=>({index,label:sim.mode==='duel'?`Round ${index+1}`:`Stage ${index+1}`,bonus:false}));if(sim.mode!=='duel')for(let i=0;i<(sim.mode==='arcade'?4:3);i++)rows.push({index:16+i,label:`Bonus ${i+1}`,bonus:true});return rows;}
  function build(){panel=document.createElement('section');panel.className='level-overlay';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Select an original level');panel.innerHTML='<div class="level-card"><h2>Select level</h2><p>LEVEL cheat · original levels in the current mode. Resets health, lives, and magic; keeps your selected heroes and game mode.</p><div data-level-main class="level-grid"></div><p data-bonus-title>Original bonus stages</p><div data-level-bonus class="level-grid"></div><p class="level-status" role="status"></p><button class="level-close" data-level-close>Cancel</button></div>';document.querySelector('#game-shell').append(panel);panel.querySelector('[data-level-close]').addEventListener('click',()=>close());panel.addEventListener('keydown',event=>{event.stopPropagation();if(event.code==='Escape'){event.preventDefault();close();return;}if(event.code==='Tab'){const items=[...panel.querySelectorAll('button')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});}
  function open(){if(!available())return false;if(!panel)build();if(!panel.hidden)return true;const g=getGame();g.hdPreview?.close();g.mapOverlay?.close();openedGame=g;previouslyPaused=!!g.paused;restoreFocus=document.activeElement;if(!g.paused)g.pause();g.input?.clear();const main=panel.querySelector('[data-level-main]'),bonus=panel.querySelector('[data-level-bonus]');main.replaceChildren();bonus.replaceChildren();for(const row of choices()){const button=document.createElement('button');button.dataset.levelIndex=String(row.index);button.textContent=row.label;if(row.index===g.simulation.state.stageIndex){button.className='level-current';button.setAttribute('aria-current','true');}button.addEventListener('click',()=>{const result=onSelect(row.index);if(result?.ok)close({resume:false,focus:false});else panel.querySelector('.level-status').textContent='This level is not available in the current mode.';});(row.bonus?bonus:main).append(button);}panel.querySelector('[data-bonus-title]').hidden=g.simulation.mode==='duel';panel.querySelector('.level-status').textContent='Select a level to start a test run.';panel.hidden=false;main.querySelector('button').focus();return true;}
  function close({resume=true,focus=true}={}){if(!panel||panel.hidden)return;panel.hidden=true;const g=openedGame;openedGame=null;g?.input?.clear();if(resume&&g&&!previouslyPaused&&g.paused)g.pause();if(focus)restoreFocus?.focus?.({preventScroll:true});}
  function dispose(){close({resume:false,focus:false});panel?.remove();styles.remove();}
  return{open,close,toggle:()=>panel&&!panel.hidden?(close(),false):open(),available,choices,dispose,get isOpen(){return !!panel&&!panel.hidden;}};
}
